fn funding_counts<'a>(
    entries: impl IntoIterator<Item = &'a CapturedFundingEntry>,
) -> HashMap<&'a CapturedFundingEntry, usize> {
    let mut counts = HashMap::new();
    for entry in entries {
        *counts.entry(entry).or_insert(0) += 1;
    }
    counts
}

